from collections import deque
def comps(g,bg):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; c=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cs=[]
                while q:
                    y,x=q.popleft(); cs.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; q.append((ny,nx))
                c.append((col,sorted(cs)))
    return c
